/* -------------------- GENERIC CONFIG SYNC -------------------- */

const handleConfigSync = async (table, data, mapFn, options = {}) => {
    const pool = await connectDB();
    const transaction = new sql.Transaction(pool);
    await transaction.begin();
    try {
        const keptIds = [];
        for (const item of data) {
            let { query, params } = mapFn(item);
            keptIds.push(params.id);
            
            const checkReq = transaction.request();
            checkReq.input('id', params.id);
            const check = await checkReq.query(`SELECT 1 FROM ${table} WHERE id = @id`);
            
            if (check.recordset.length > 0) {
               const match = query.match(/INSERT INTO\s+[a-z_]+\s*\(([^)]+)\)\s*VALUES\s*\(([^)]+)\)/i);
               if (match) {
                   const cols = match[1].split(',').map(s=>s.trim());
                   const vals = match[2].split(',').map(s=>s.trim());
                   const setClause = cols.map((c, i) => `${c} = ${vals[i]}`).filter(c => !c.startsWith('id =')).join(', ');
                   query = `UPDATE ${table} SET ${setClause} WHERE id = @id`;
               } else {
                   const delReq = transaction.request();
                   delReq.input('id', params.id);
                   await delReq.query(`DELETE FROM ${table} WHERE id = @id`);
               }
            }

            const req = transaction.request();
            Object.entries(params).forEach(([k, v]) => req.input(k, v !== undefined ? v : null)); 
            await req.query(query);
        }

        if (options.replace) {
            const existingRows = await transaction.request().query(`SELECT id FROM ${table}`);
            const keptSet = new Set(keptIds);
            for (const row of existingRows.recordset) {
                if (!keptSet.has(row.id)) {
                    await transaction.request()
                        .input('delId', row.id)
                        .query(`BEGIN TRY DELETE FROM ${table} WHERE id = @delId; END TRY BEGIN CATCH END CATCH`);
                }
            }
        }

        await transaction.commit();
    } catch (e) {
        console.error("TRANSACTION ABORTED IN TABLE", table, "ERROR:", e);
        await transaction.rollback();
        throw e;
    }
};

