/* -------------------- ERP QUEUE SYNC -------------------- */
app.post('/api/v1/erp/process-queue', asyncHandler(async (req, res) => {
    if (forbid(req, res, canRunIntegrations(req.user), 'integrations require ADMIN/HR')) return;
    const pool = await connectDB();
    
    const pendingReq = await pool.request().query(`
        SELECT * FROM Bioeel_Integration.dbo.Queue 
        WHERE status = 'pending' 
        AND doc_type IN ('DEPARTMENT_SYNC', 'SCHEDULE_SYNC', 'EMPLOYEE_SYNC')
        ORDER BY timestamp ASC
    `);
    const items = pendingReq.recordset;

    let processedCount = 0;
    let errorCount = 0;

    for (const item of items) {
        let currentStatus = 'processed';
        let errorMessage = null;

        try {
            const data = JSON.parse(item.content_json);

            if (item.doc_type === 'DEPARTMENT_SYNC') {
                await handleConfigSync('departments', data, (d) => ({
                    query: `
                        INSERT INTO departments (id, name, company_id, manager_id, email_notifications, source) VALUES (@id, @name, @cid, @mid, @en, @source)
                    `,
                    params: { id: d.id, name: d.name, cid: d.companyId, mid: d.managerId, en: d.emailNotifications ? 1 : 0, source: 'ERP' }
                }));
            } else if (item.doc_type === 'SCHEDULE_SYNC') {
                await handleConfigSync('work_schedules', data, (s) => ({
                    query: `
                        INSERT INTO work_schedules (id, name, start_time, end_time, crosses_midnight, erp_id, source) VALUES (@id, @name, @start, @end, @cross, @erpId, @source)
                    `,
                    params: { id: s.id, name: s.name, start: s.startTime, end: s.endTime, cross: s.crossesMidnight ? 1 : 0, erpId: s.erpId || null, source: 'ERP' }
                }));
            } else if (item.doc_type === 'EMPLOYEE_SYNC') {
                const mappedData = data.map(u => {
                    const isBioeel = u.email && (u.email.endsWith('@bioeel.ro') || u.email.endsWith('@techgroup.ro'));
                    const authType = isBioeel ? 'MICROSOFT' : 'PIN';
                    
                    let empStatus = u.employmentStatus || 'ACTIVE';
                    if (u.terminationDate && new Date(u.terminationDate) <= new Date()) {
                        empStatus = 'TERMINATED';
                    }

                    return { ...u, authType, employmentStatus: empStatus };
                });

                await handleConfigSync('users', mappedData, (u) => ({
                    query: `
                        INSERT INTO users (id, erp_id, company_id, department_id, assigned_office_id, main_schedule_id, name, email, auth_type, roles, contract_hours, is_validated, requires_gps, employment_status, timekeeper_id, first_name, last_name, hire_date, termination_date, source) 
                        VALUES (@id, @erpId, @cid, @did, @oid, @sid, @name, @email, @auth, @roles, @hours, @val, @gps, @status, @timekeeperId, @firstName, @lastName, @hireDate, @terminationDate, @source)
                    `,
                    params: {
                        id: u.id, erpId: u.erpId, cid: u.companyId, did: u.departmentId, oid: u.assignedOfficeId, sid: u.mainScheduleId,
                        name: u.name, email: u.email, auth: u.authType, roles: JSON.stringify(u.roles), hours: u.contractHours, val: u.isValidated?1:0, gps: u.requiresGPS?1:0, status: u.employmentStatus, timekeeperId: u.timekeeperId,
                        firstName: u.firstName, lastName: u.lastName, hireDate: u.hireDate, terminationDate: u.terminationDate, source: 'ERP'
                    }
                }));
            }
            
        } catch (e) {
            currentStatus = 'error';
            errorMessage = e.message;
            errorCount++;
        }

        await pool.request()
            .input('id', item.id)
            .input('status', currentStatus)
            .input('error', errorMessage ? JSON.stringify({ error: errorMessage }) : '{"success": true}')
            .query(`UPDATE Bioeel_Integration.dbo.Queue SET status = @status, response_content = @error, timestamp = GETDATE() WHERE id = @id`);
        
        if (currentStatus === 'processed') processedCount++;
    }

    res.json({ success: true, processedCount, errorCount });
}));

