/* -------------------- BIOEELAUTH INTEGRATION -------------------- */

// Disable SSL verification for internal proxy/self-signed certs
// Only on developer machines (internal proxy cert for apps.bioeel.ro). Never on the production host,
// where the call goes to http://localhost:3006 and Microsoft signing keys must be fetched over verified TLS.
if (!(os.hostname().toUpperCase() === 'BE-APL01' || process.env.NODE_ENV === 'production')) {
    process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';
}

const AUTH_API_BASE = process.env.BIOEEL_AUTH_API || 
    (os.hostname().toUpperCase() === 'BE-APL01' || process.env.NODE_ENV === 'production'
        ? 'http://localhost:3006/api/auth' 
        : 'https://apps.bioeel.ro/pos/api/auth');

async function syncUsersWithBioeelAuth() {
    console.log(`Starting users sync with BioeelAuth REST API (Target: ${AUTH_API_BASE})...`);
    try {
        const pool = await connectDB();
        const response = await fetch(`${AUTH_API_BASE}/pontaj-employees`);
        if (!response.ok) {
            throw new Error(`Failed to fetch employees: ${response.statusText}`);
        }
        const data = await response.json();
        const employees = data.employees || [];
        console.log(`Fetched ${employees.length} employees from BioeelAuth.`);

        const companies = new Set();
        const departments = new Map();

        for (const emp of employees) {
            if (emp.CompanieCode) {
                companies.add(emp.CompanieCode);
                if (emp.Departament) {
                    departments.set(emp.Departament, emp.CompanieCode);
                }
            }
        }

        // Batch-preload existing companies, departments, and users in 3 queries instead of 2-3 queries per employee (eliminates N+1)
        const [compRows, deptRows, userRows] = await Promise.all([
            pool.request().query('SELECT id FROM companies'),
            pool.request().query('SELECT id, name FROM departments'),
            pool.request().query('SELECT id, email, erp_id, source, employment_status FROM users')
        ]);
        const existingCompanies = new Set(compRows.recordset.map(c => c.id));
        const deptIdByName = new Map(deptRows.recordset.map(d => [d.name, d.id]));
        const userByEmail = new Map();
        const userByErpId = new Map();
        for (const u of userRows.recordset) {
            if (u.email) userByEmail.set(u.email.toLowerCase().trim(), u);
            if (u.erp_id) userByErpId.set(String(u.erp_id), u);
        }

        for (const compCode of companies) {
            if (!existingCompanies.has(compCode)) {
                await pool.request()
                    .input('id', compCode)
                    .input('name', compCode === 'BIOEEL' ? 'Bioeel SRL' : compCode)
                    .query('INSERT INTO companies (id, name) VALUES (@id, @name)');
                existingCompanies.add(compCode);
            }
        }

        for (const [deptName, compCode] of departments.entries()) {
            if (!deptIdByName.has(deptName)) {
                const deptId = `dep-${deptName.toLowerCase().replace(/[^a-z0-9]/g, '-')}`;
                await pool.request()
                    .input('id', deptId)
                    .input('name', deptName)
                    .input('cid', compCode)
                    .query('INSERT INTO departments (id, name, company_id, manager_id, email_notifications) VALUES (@id, @name, @cid, NULL, 0)');
                deptIdByName.set(deptName, deptId);
            }
        }

        for (const emp of employees) {
            const email = emp.Email ? emp.Email.toLowerCase().trim() : null;
            if (!email) continue;

            const erpIdStr = String(emp.Marca);
            const dbUser = userByEmail.get(email) || userByErpId.get(erpIdStr) || null;

            const status = emp.EsteActiv ? 'ACTIVE' : 'TERMINATED';
            const deptId = emp.Departament ? (deptIdByName.get(emp.Departament) || null) : null;
            
            const nameParts = emp.NumePrenume ? emp.NumePrenume.trim().split(' ') : [];
            const lastName = nameParts[0] || '';
            const firstName = nameParts.slice(1).join(' ') || '';

            if (dbUser) {
                await pool.request()
                    .input('id', dbUser.id)
                    .input('erpId', erpIdStr)
                    .input('name', emp.NumePrenume)
                    .input('email', email)
                    .input('cid', emp.CompanieCode || null)
                    .input('did', deptId)
                    .input('status', status)
                    .input('firstName', firstName)
                    .input('lastName', lastName)
                    .query(`
                        UPDATE users 
                        SET erp_id = @erpId, name = @name, email = @email, company_id = @cid, department_id = @did, employment_status = @status, source = 'ERP',
                            first_name = @firstName, last_name = @lastName
                        WHERE id = @id
                    `);
            } else {
                const newId = `u-${emp.Marca}`;
                const defaultRoles = JSON.stringify(['EMPLOYEE']);
                await pool.request()
                    .input('id', newId)
                    .input('erpId', erpIdStr)
                    .input('name', emp.NumePrenume)
                    .input('email', email)
                    .input('cid', emp.CompanieCode || null)
                    .input('did', deptId)
                    .input('auth', 'PIN')
                    .input('roles', defaultRoles)
                    .input('status', status)
                    .input('firstName', firstName)
                    .input('lastName', lastName)
                    .query(`
                        INSERT INTO users (id, erp_id, company_id, department_id, name, email, auth_type, roles, contract_hours, is_validated, requires_gps, employment_status, source, first_name, last_name) 
                        VALUES (@id, @erpId, @cid, @did, @name, @email, @auth, @roles, 8, 1, 1, @status, 'ERP', @firstName, @lastName)
                    `);
            }
        }

        const activeMarcas = new Set(employees.map(emp => String(emp.Marca)));
        if (activeMarcas.size > 0) {
            for (const lu of userRows.recordset) {
                if (lu.source === 'ERP' && lu.erp_id && !activeMarcas.has(String(lu.erp_id)) && lu.employment_status !== 'TERMINATED') {
                    await pool.request()
                        .input('id', lu.id)
                        .query("UPDATE users SET employment_status = 'TERMINATED' WHERE id = @id");
                }
            }
        }

        console.log("Users sync completed successfully.");
        return { success: true, count: employees.length };
    } catch (e) {
        console.error("Error in syncUsersWithBioeelAuth:", e);
        return { success: false, error: e.message };
    }
}

// Simple in-memory brute-force protection for PIN login (per IP + email).
const LOGIN_MAX_ATTEMPTS = 5;
const LOGIN_WINDOW_MS = 15 * 60 * 1000;
const loginAttempts = new Map();

const isLoginBlocked = (key) => {
    const entry = loginAttempts.get(key);
    if (!entry) return false;
    if (Date.now() - entry.firstAt > LOGIN_WINDOW_MS) {
        loginAttempts.delete(key);
        return false;
    }
    return entry.count >= LOGIN_MAX_ATTEMPTS;
};

const registerFailedLogin = (key) => {
    const entry = loginAttempts.get(key);
    if (!entry || Date.now() - entry.firstAt > LOGIN_WINDOW_MS) {
        loginAttempts.set(key, { count: 1, firstAt: Date.now() });
    } else {
        entry.count++;
    }
};

// On-demand sync (triggered by unknown emails at login) runs at most once per interval.
const ON_DEMAND_SYNC_INTERVAL_MS = 5 * 60 * 1000;
let lastOnDemandSyncAt = 0;

// 2FA Enrollment OTP Challenges: userId -> { code, expiresAt, attempts }
const OTP_TTL_MS = 10 * 60 * 1000;
const pending2faCodes = new Map();

const getOrCreate2FACode = (userId, forceNew = false) => {
    const now = Date.now();
    const existing = pending2faCodes.get(userId);
    if (!forceNew && existing && now < existing.expiresAt && existing.attempts < 5) {
        return existing.code;
    }
    const code = String(crypto.randomInt(100000, 1000000));
    pending2faCodes.set(userId, { code, expiresAt: now + OTP_TTL_MS, attempts: 0 });
    return code;
};

const handlePinDeviceAnd2FA = async (req, res, pool, user) => {
    const deviceToken = readDeviceCookie(req);
    const deviceHash = deviceToken ? hashDeviceToken(deviceToken) : null;

    if (user.employment_status !== 'ACTIVE') {
        await pool.request().input('id', user.id).query("UPDATE users SET employment_status = 'ACTIVE' WHERE id = @id");
        user.employment_status = 'ACTIVE';
    }

    // Case 1: User already has an enrolled phone and the cookie matches -> instant daily login
    if (user.trusted_device_hash && deviceHash === user.trusted_device_hash) {
        issueSession(req, res, user.id);
        return res.json({ success: true, user: mapUserRow(user) });
    }

    // Case 2 (Option C): User already has an enrolled phone, but login comes from ANOTHER phone/browser -> block
    if (user.trusted_device_hash && deviceHash !== user.trusted_device_hash) {
        return res.status(403).json({
            success: false,
            deviceLocked: true,
            error: `Contul este deja asociat cu un alt dispozitiv (${user.trusted_device_label || 'Telefon înrolat'}). Pentru schimbarea telefonului, solicitați resetarea dispozitivului la HR / Administrator.`
        });
    }

    // Case 3 (Option B): First login (no device enrolled yet, or reset by HR) -> require 2FA code to bind this phone
    const code = getOrCreate2FACode(user.id, false);
    const challengeToken = sign2FAChallenge(user.id);
    console.log(`\n🔐 [2FA ÎNROLARE DISPOZITIV] Utilizator: ${user.name} (${user.email}) | Cod 2FA (10 min): ${code}\n`);
    await createNotification(pool, {
        userId: user.id,
        title: 'Cod 2FA înrolare telefon',
        message: `Codul de verificare pentru înrolarea telefonului este: ${code} (valabil 10 minute).`,
        type: 'INFO'
    });

    return res.json({
        success: false,
        requires2FA: true,
        challengeToken,
        email: user.email,
        message: 'Introduceți codul de verificare 2FA din 6 cifre (trimis pe email / disponibil la HR) pentru a asocia acest telefon cu contul dumneavoastră.'
    });
};

// Endpoint de login securizat cu PIN (BioeelAuth)
app.post('/api/v1/auth/login-pin', asyncHandler(async (req, res) => {
    const { email, pin } = req.body;
    if (!email || !pin) {
        return res.status(400).json({ success: false, error: 'Email and PIN are required.' });
    }

    const pool = await connectDB();
    
    const attemptKey = `${req.ip}|${String(email).toLowerCase().trim()}`;
    if (isLoginBlocked(attemptKey)) {
        return res.status(429).json({ success: false, error: 'Prea multe încercări eșuate. Încercați din nou peste 15 minute.' });
    }

    let userResult = await pool.request()
        .input('email', email.toLowerCase().trim())
        .query('SELECT * FROM users WHERE email = @email');

    if (userResult.recordset.length === 0 && Date.now() - lastOnDemandSyncAt > ON_DEMAND_SYNC_INTERVAL_MS) {
        lastOnDemandSyncAt = Date.now();
        console.log(`User ${email} not found locally during PIN login. Triggering sync...`);
        const syncResult = await syncUsersWithBioeelAuth();
        if (syncResult.success) {
            userResult = await pool.request()
                .input('email', email.toLowerCase().trim())
                .query('SELECT * FROM users WHERE email = @email');
        }
    }

    if (userResult.recordset.length === 0) {
        registerFailedLogin(attemptKey);
        return res.status(404).json({ success: false, error: 'Utilizator negăsit.' });
    }

    const user = userResult.recordset[0];
    
    if (user.employment_status === 'SUSPENDED' || user.employment_status === 'TERMINATED') {
        return res.status(403).json({ success: false, error: 'Contul dumneavoastră este suspendat sau inactiv.' });
    }

    try {
        const response = await fetch(`${AUTH_API_BASE}/pontaj-check`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                pin: pin,
                marca: user.erp_id ? user.erp_id.toString() : null
            })
        });

        const data = await response.json();
        
        if (response.ok && data.success) {
            const mappedUser = {
                ...user,
                roles: user.roles ? JSON.parse(user.roles) : [],
                alternativeScheduleIds: user.alternative_schedule_ids ? JSON.parse(user.alternative_schedule_ids) : [],
                companyId: user.company_id,
                departmentId: user.department_id,
                assignedOfficeId: user.assigned_office_id,
                mainScheduleId: user.main_schedule_id,
                contractHours: user.contract_hours,
                isValidated: user.is_validated,
                requiresGPS: user.requires_gps,
                erpId: user.erp_id,
                authType: user.auth_type,
                employmentStatus: user.employment_status,
                timekeeperId: user.timekeeper_id,
                firstName: user.first_name,
                lastName: user.last_name,
                hireDate: user.hire_date,
                terminationDate: user.termination_date,
                source: user.source
            };

            if (user.employment_status !== 'ACTIVE') {
                await pool.request()
                    .input('id', user.id)
                    .query("UPDATE users SET employment_status = 'ACTIVE' WHERE id = @id");
                mappedUser.employmentStatus = 'ACTIVE';
            }

            loginAttempts.delete(attemptKey);
            return await handlePinDeviceAnd2FA(req, res, pool, user);
            issueSession(req, res, user.id);
            res.json({ success: true, user: mappedUser });
        } else {
            registerFailedLogin(attemptKey);
            res.status(401).json({ success: false, error: data.message || 'PIN incorect.' });
        }
    } catch (err) {
        console.error('Error calling BioeelAuth check API:', err);
        res.status(502).json({ success: false, error: 'Eroare la conectarea cu serverul central de autentificare (BioeelAuth).' });
    }
}));

// Verificare cod 2FA și înrolare dispozitiv (1 angajat = 1 telefon înrolat)
app.post('/api/v1/auth/verify-2fa', asyncHandler(async (req, res) => {
    const { challengeToken, code } = req.body || {};
    if (!challengeToken || !code) {
        return res.status(400).json({ success: false, error: 'Lipsesc datele pentru verificarea 2FA.' });
    }
    let userId;
    try {
        userId = verify2FAChallenge(challengeToken);
    } catch {
        return res.status(401).json({ success: false, error: 'Sesiunea de verificare 2FA a expirat. Reintroduceți PIN-ul.' });
    }

    const entry = pending2faCodes.get(userId);
    if (!entry || Date.now() > entry.expiresAt) {
        pending2faCodes.delete(userId);
        return res.status(401).json({ success: false, error: 'Codul 2FA a expirat. Reintroduceți PIN-ul pentru un cod nou.' });
    }

    if (entry.code !== String(code).trim()) {
        entry.attempts++;
        if (entry.attempts >= 5) pending2faCodes.delete(userId);
        return res.status(401).json({ success: false, error: 'Cod 2FA incorect.' });
    }

    pending2faCodes.delete(userId);
    const pool = await connectDB();
    const userRes = await pool.request().input('id', userId).query('SELECT * FROM users WHERE id = @id');
    const user = userRes.recordset[0];
    if (!user || user.employment_status === 'SUSPENDED' || user.employment_status === 'TERMINATED') {
        return res.status(403).json({ success: false, error: 'Contul este inactiv sau suspendat.' });
    }

    // Dacă între timp alt dispozitiv a fost înrolat, blocăm suprascrierea neautorizată
    if (user.trusted_device_hash) {
        return res.status(403).json({ success: false, error: 'Contul are deja un dispozitiv înrolat. Solicitați resetarea la HR.' });
    }

    const { hash } = issueDeviceCookie(req, res);
    const label = describeUserAgent(req.headers['user-agent'] || '');
    await pool.request()
        .input('id', user.id)
        .input('hash', hash)
        .input('label', label)
        .query('UPDATE users SET trusted_device_hash = @hash, trusted_device_label = @label, trusted_device_enrolled_at = SYSDATETIME() WHERE id = @id');

    const updatedRes = await pool.request().input('id', user.id).query('SELECT * FROM users WHERE id = @id');
    issueSession(req, res, user.id);
    res.json({ success: true, user: mapUserRow(updatedRes.recordset[0]) });
}));

// Generare cod 2FA de înrolare de către Admin / HR / Manager / Pontator pentru un angajat din subordine
app.post('/api/v1/auth/device-code', asyncHandler(async (req, res) => {
    const { userId } = req.body || {};
    if (!userId) return res.status(400).json({ error: 'Missing userId' });
    const directory = await loadUserDirectory();
    const targetUser = directory.get(userId);
    if (!targetUser) return res.status(404).json({ error: 'Utilizator negăsit' });
    if (forbid(req, res, canManageUsers(req.user) || canManageTimesheetsOf(req.user, targetUser), 'only ADMIN/HR/Manager/Pontator of this employee can generate 2FA enrollment codes')) return;
    const code = getOrCreate2FACode(userId, true);
    res.json({ success: true, code, expiresInMinutes: 10 });
}));

// Resetare telefon asociat (Device Binding) de către Admin / HR / Manager / Pontator (ex. când angajatul își schimbă telefonul)
app.post('/api/v1/auth/device-reset', asyncHandler(async (req, res) => {
    const { userId } = req.body || {};
    if (!userId) return res.status(400).json({ error: 'Missing userId' });
    const directory = await loadUserDirectory();
    const targetUser = directory.get(userId);
    if (!targetUser) return res.status(404).json({ error: 'Utilizator negăsit' });
    if (forbid(req, res, canManageUsers(req.user) || canManageTimesheetsOf(req.user, targetUser), 'only ADMIN/HR/Manager/Pontator of this employee can reset bound devices')) return;
    const pool = await connectDB();
    await pool.request()
        .input('id', userId)
        .query('UPDATE users SET trusted_device_hash = NULL, trusted_device_label = NULL, trusted_device_enrolled_at = NULL WHERE id = @id');
    pending2faCodes.delete(userId);
    await createNotification(pool, {
        userId,
        title: 'Dispozitiv resetat',
        message: 'Dispozitivul asociat contului tău a fost resetat. La următoarea autentificare cu PIN poți înrola noul telefon.',
        type: 'INFO'
    });
    res.json({ success: true });
}));

// Login Microsoft: ID token-ul obținut de MSAL este validat pe server, apoi se emite sesiunea.
app.post('/api/v1/auth/login-microsoft', asyncHandler(async (req, res) => {
    const { idToken } = req.body || {};
    if (!idToken) return res.status(400).json({ success: false, error: 'Lipsește token-ul Microsoft.' });

    let email;
    try {
        email = await verifyMicrosoftIdToken(idToken);
    } catch (err) {
        console.error('Microsoft token validation failed:', err.message);
        const serverSide = /configured|download|fetch/i.test(err.message);
        return res.status(serverSide ? 502 : 401).json({
            success: false,
            error: serverSide ? 'Serverul nu poate verifica momentan autentificarea Microsoft. Folosiți PIN-ul.' : 'Autentificare Microsoft invalidă.'
        });
    }

    const pool = await connectDB();
    const findUser = () => pool.request().input('email', email).query('SELECT * FROM users WHERE LOWER(email) = @email');
    let userResult = await findUser();
    if (userResult.recordset.length === 0 && Date.now() - lastOnDemandSyncAt > ON_DEMAND_SYNC_INTERVAL_MS) {
        lastOnDemandSyncAt = Date.now();
        const syncResult = await syncUsersWithBioeelAuth();
        if (syncResult.success) userResult = await findUser();
    }
    if (userResult.recordset.length === 0) {
        return res.status(403).json({ success: false, error: `Contul Microsoft (${email}) nu este asociat unui angajat activ.` });
    }
    const user = userResult.recordset[0];
    if (user.employment_status === 'SUSPENDED' || user.employment_status === 'TERMINATED') {
        return res.status(403).json({ success: false, error: 'Contul dumneavoastră este suspendat sau inactiv.' });
    }
    issueSession(req, res, user.id);
    res.json({ success: true, user: mapUserRow(user) });
}));

